// Package: Microsoft.Extensions.AI
// Composes a grounded prompt from system rules, retrieved context, conversation history, and user input.

using Microsoft.Extensions.AI;

public sealed class PromptComposer
{
    private readonly string _systemInstructions;

    public PromptComposer(string systemInstructions)
    {
        _systemInstructions = string.IsNullOrWhiteSpace(systemInstructions)
            ? throw new ArgumentException("System instructions cannot be empty.", nameof(systemInstructions))
            : systemInstructions;
    }

    public ChatMessage Compose(
        IReadOnlyList<string> contextChunks,
        IReadOnlyList<ChatMessage> history,
        string userMessage)
    {
        ArgumentNullException.ThrowIfNull(contextChunks);
        ArgumentNullException.ThrowIfNull(history);
        ArgumentNullException.ThrowIfNull(userMessage);

        var context = string.Join(
            "\n---\n",
            contextChunks.Select((text, i) => $"[Source {i + 1}] {text}"));

        var historyText = FormatHistory(history);

        var userPrompt = $"""
Context:
{context}

Conversation:
{historyText}

Question:
{userMessage}
""";

        var systemMessage = new ChatMessage(ChatRole.System, _systemInstructions);
        var userMessageBlock = new ChatMessage(ChatRole.User, userPrompt);

        return systemMessage with
        {
            Followups = [userMessageBlock]
        };
    }

    private static string FormatHistory(IReadOnlyList<ChatMessage> history)
    {
        if (history.Count == 0)
        {
            return "(none)";
        }

        var formatted = new System.Text.StringBuilder();
        foreach (var message in history)
        {
            formatted.Append($"{message.Role}: {message.Text}");
            formatted.AppendLine();
        }

        return formatted.ToString();
    }
}

